#!/usr/bin/env python3
"""r3_qwen_gen.py -- DEV and TRAINING paraphrases for the rewording-robustness method tracks (rule R3), generated by
Qwen/Qwen2.5-72B-Instruct-AWQ (the R2 generator, NOT the R3 generator) in vLLM 0.10.2 on ONE card.

Prompt = R1 rob_common.GEN_PROMPT (attempt 1) / GEN_PROMPT + GEN_RETRY_SUFFIX (attempt 2), one user turn, the model's own
default chat template, greedy decoding (temperature 0, seed 0), max 300 new tokens (= r2_gen.py). Mechanical checks =
rob_common.mechanical_check with the frozen mtq_lib.parse_time (in-session, gold-free). Never reads answers.

Stages (resume-safe; every stage appends to its JSONL and skips quids already written):
  1. dev attempt 1  : all dev_sel2000 questions
  2. dev attempt 2  : dev questions whose attempt-1 output failed a mechanical check (in-session; the LLM judge runs
                      afterwards, outside this script, and does not trigger a retry for dev)
  3. training       : the 5% training list in the registered order (r3_common.training_order), ONE attempt, in chunks
                      of --chunk prompts; before each chunk: stop if elapsed + projected chunk time > --deadline_s
Engine: --engine graph (CUDA graphs / torch.compile, vLLM default) with automatic fallback to eager (= R2) if the
graph engine fails to start; gpu_memory_utilization from --gpu_mem (computed by the job from free memory).
  python3 r3_qwen_gen.py --dev dev_qtext.json --train_order train_order.json --train_q /data/questions/train.json \
      --out /kpct/robustness_r3/gen --deadline_s 2400 --gpu_mem 0.49
"""
import argparse, glob, hashlib, json, os, sys, time


def sha(s):
    return hashlib.sha256(s.encode('utf-8')).hexdigest()


def read_jsonl(p):
    if not os.path.exists(p):
        return []
    return [json.loads(l) for l in open(p) if l.strip()]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--dev', required=True); ap.add_argument('--train_order', required=True)
    ap.add_argument('--train_q', required=True); ap.add_argument('--out', required=True)
    ap.add_argument('--model', default='Qwen/Qwen2.5-72B-Instruct-AWQ')
    ap.add_argument('--max_tokens', type=int, default=300)
    ap.add_argument('--gpu_mem', type=float, default=0.49); ap.add_argument('--max_model_len', type=int, default=2048)
    ap.add_argument('--max_num_batched_tokens', type=int, default=2048)
    ap.add_argument('--engine', default='graph', choices=['graph', 'eager'])
    ap.add_argument('--deadline_s', type=float, required=True, help='stop starting training chunks past this wall time')
    ap.add_argument('--chunk', type=int, default=1000)
    ap.add_argument('--code', default='/kpct/robustness_r3/code'); ap.add_argument('--mtq', default='/kpct/executor/struct')
    a = ap.parse_args()
    t_start = time.time()
    sys.path.insert(0, a.code); sys.path.insert(0, a.mtq)
    import rob_common as RC
    import mtq_lib as L
    os.makedirs(a.out, exist_ok=True)
    stats_p = os.path.join(a.out, 'gen_stats.json')
    stats = json.load(open(stats_p)) if os.path.exists(stats_p) else dict(sessions=[])
    sess = dict(start_utc=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()), engine_requested=a.engine, gpu_mem=a.gpu_mem,
                max_model_len=a.max_model_len, max_num_batched_tokens=a.max_num_batched_tokens, deadline_s=a.deadline_s,
                chunk=a.chunk, stages={})
    stats['sessions'].append(sess)

    def save_stats():
        json.dump(stats, open(stats_p + '.tmp', 'w'), indent=1); os.replace(stats_p + '.tmp', stats_p)

    from vllm import LLM, SamplingParams
    import vllm
    kw = dict(model=a.model, dtype='float16', max_model_len=a.max_model_len, gpu_memory_utilization=a.gpu_mem, seed=0,
              trust_remote_code=False, max_num_batched_tokens=a.max_num_batched_tokens)
    llm, engine = None, None
    for eng in ([a.engine] if a.engine == 'eager' else ['graph', 'eager']):
        t0 = time.time()
        try:
            llm = LLM(enforce_eager=(eng == 'eager'), **kw)
            engine = eng
            sess['init_s_' + eng] = round(time.time() - t0, 1)
            break
        except Exception as e:                       # registered fallback: graph -> eager (R2 engine)
            sess['engine_error_' + eng] = repr(e)[:2000]
            sess['init_s_' + eng] = round(time.time() - t0, 1)
            save_stats()
            print('ENGINE_FAIL', eng, repr(e)[:500], flush=True)
            try:
                import gc, torch
                del llm; gc.collect(); torch.cuda.empty_cache()
            except Exception:
                pass
            llm = None
    if llm is None:
        save_stats(); sys.exit(3)
    sess['engine'] = engine
    tok = llm.get_tokenizer()
    sp = SamplingParams(temperature=0.0, max_tokens=a.max_tokens, seed=0)
    snap = sorted(glob.glob(f"/hf/hub/models--{a.model.replace('/', '--')}/snapshots/*"))
    cfg = os.path.join(snap[-1], 'config.json') if snap else None
    stats['model'] = dict(model=a.model, snapshot=os.path.basename(snap[-1]) if snap else None,
                          config_sha256=hashlib.sha256(open(cfg, 'rb').read()).hexdigest() if cfg and os.path.exists(cfg) else None,
                          vllm=vllm.__version__, chat_template_sha256=sha(tok.chat_template or ''),
                          decoding=dict(temperature=0.0, seed=0, max_tokens=a.max_tokens),
                          gen_prompt_sha256=sha(RC.GEN_PROMPT), retry_suffix_sha256=sha(RC.GEN_RETRY_SUFFIX))
    save_stats()

    def render(p):
        return tok.apply_chat_template([{'role': 'user', 'content': p}], tokenize=False, add_generation_prompt=True)

    def run(rows, out_path, stage):
        """rows: [{quid, attempt, prompt, original}] -> append {quid, attempt, text, finish_reason, n_out, prompt_sha256,
        paraphrase, kept, mech_ok, mech_reasons} to out_path"""
        if not rows:
            return [], 0.0
        texts = [render(r['prompt']) for r in rows]
        t1 = time.time()
        outs = llm.generate(texts, sp, use_tqdm=False)
        dt = time.time() - t1
        res = []
        with open(out_path, 'a') as f:
            for r, o in zip(rows, outs):
                g = o.outputs[0]
                js = RC.extract_json(g.text)
                para = js.get('paraphrase') if isinstance(js, dict) else None
                kept = js.get('kept_verbatim') if isinstance(js, dict) else None
                if isinstance(para, str):
                    ok, rs = RC.mechanical_check(r['original'], para, kept, L.parse_time)
                    para = para.strip()
                else:
                    ok, rs, para = False, ['no_json'], None
                rec = dict(quid=r['quid'], attempt=r['attempt'], text=g.text, finish_reason=g.finish_reason, n_out=len(g.token_ids),
                           prompt_sha256=sha(r['prompt']), paraphrase=para, kept=kept, mech_ok=ok, mech_reasons=rs)
                f.write(json.dumps(rec, ensure_ascii=False) + '\n')
                res.append(rec)
        st = sess['stages'].setdefault(stage, dict(n=0, gen_s=0.0, mech_ok=0, finish_length=0))
        st['n'] += len(res); st['gen_s'] = round(st['gen_s'] + dt, 1); st['mech_ok'] += sum(x['mech_ok'] for x in res)
        st['finish_length'] += sum(x['finish_reason'] == 'length' for x in res)
        save_stats()
        print(stage, len(res), round(dt, 1), 's', flush=True)
        return res, dt

    # ---------------------------------------------------------------- dev
    dev = json.load(open(a.dev))
    byq = {int(r['quid']): r for r in dev}
    p1 = os.path.join(a.out, 'dev_attempt1_gen.jsonl'); p2 = os.path.join(a.out, 'dev_attempt2_gen.jsonl')
    done1 = {int(r['quid']): r for r in read_jsonl(p1)}
    todo = [dict(quid=q, attempt=1, prompt=RC.GEN_PROMPT.format(question=byq[q]['question']), original=byq[q]['question'])
            for q in sorted(byq) if q not in done1]
    res, dt1 = run(todo, p1, 'dev_attempt1')
    rate0 = (dt1 / len(res)) if res else None
    for r in res:
        done1[r['quid']] = r
    done2 = {int(r['quid']) for r in read_jsonl(p2)}
    rej = [q for q in sorted(done1) if not done1[q]['mech_ok'] and q not in done2]
    todo2 = []
    for q in rej:
        prev = done1[q]['paraphrase'] if done1[q]['paraphrase'] else (done1[q]['text'] or '')
        todo2.append(dict(quid=q, attempt=2, prompt=RC.GEN_PROMPT.format(question=byq[q]['question']) + RC.GEN_RETRY_SUFFIX.format(previous=prev),
                          original=byq[q]['question']))
    run(todo2, p2, 'dev_attempt2')
    # ---------------------------------------------------------------- training (registered order, deadline)
    order = [int(q) for q in json.load(open(a.train_order))]
    want = set(order)
    tq = {int(r['quid']): r['question'] for r in json.load(open(a.train_q)) if int(r['quid']) in want}
    pt = os.path.join(a.out, 'train_gen.jsonl')
    donet = {int(r['quid']) for r in read_jsonl(pt)}
    rest = [q for q in order if q not in donet]
    last_rate = rate0          # projected s/prompt: dev attempt-1 rate until the first training chunk is measured
    stopped = None
    for s in range(0, len(rest), a.chunk):
        ch = rest[s:s + a.chunk]
        el = time.time() - t_start
        proj = (len(ch) * last_rate) if last_rate else 0.0
        if el + proj > a.deadline_s:
            stopped = dict(reason='deadline', elapsed_s=round(el, 1), projected_chunk_s=round(proj, 1), remaining=len(rest) - s)
            break
        rows = [dict(quid=q, attempt=1, prompt=RC.GEN_PROMPT.format(question=tq[q]), original=tq[q]) for q in ch]
        res, dt = run(rows, pt, 'train')
        last_rate = dt / max(1, len(ch))
    sess['train_stopped'] = stopped
    sess['train_written_total'] = len({int(r['quid']) for r in read_jsonl(pt)})
    sess['end_utc'] = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()); sess['wall_s'] = round(time.time() - t_start, 1)
    save_stats()
    print(json.dumps({k: v for k, v in sess.items() if k != 'stages'})[:1500], flush=True)


if __name__ == '__main__':      # vLLM spawns its engine core with multiprocessing 'spawn', which re-imports this file
    main()
